def count_colors(block):
    counts = {}
    for row in block:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    return counts

def find_dominant_non5(counts):
    """Find dominant non-5 color, return 5 if no clear non-5 or all-5"""
    non5_counts = {k: v for k, v in counts.items() if k != 5}
    if not non5_counts:
        return 5
    if max(non5_counts.values()) == 0:
        return 5
    for color, count in sorted(non5_counts.items(), key=lambda x: (-x[1], x[0])):
        return color
    return 5

