            block.append(input_grid[i][c*4:(c+1)*4])

        counts = count_colors(block)
        dominant = find_dominant_non5(counts)
        print(f"Block ({r},{c}): {counts}, dominant = {dominant}")
        row_out.append(dominant)
    output.append(row_out)

