def compute_output(in_grid):
    output = []
    for or_ in range(4):
        row = []
        for oc in range(4):
            block = [in_grid[or_*3+i][oc*3:(oc+1)*3] for i in range(3)]
            counts = {}
            for r in block:
                for c in r:
                    counts[c] = counts.get(c, 0) + 1

            non5_colors = {k: v for k, v in counts.items() if k != 5}

